def month_label(date_text):
    """Short month name of an ISO date."""
    MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

    # Extract month part from the date string (format: YYYY-MM-DD)
    parts = date_text.split('-')
    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {date_text}")

    try:
        month_num = int(parts[1])
    except ValueError:
        raise ValueError(f"Invalid month number: {parts[1]}")

    if month_num < 1 or month_num > 12:
        raise ValueError(f"Month number out of range: {month_num}")

    return MONTHS[month_num - 1]
