from settings_store import load


def get_setting(key, default=None):
    """One saved setting, or default when it is not saved."""
    settings = load()
    if isinstance(settings, dict):
        return settings.get(key, default)
    elif isinstance(settings, list):
        # Assume list of dicts or key-value pairs
        for item in settings:
            if isinstance(item, dict) and item.get(key) is not None:
                return item[key]
            # Handle case where item is a tuple (key, value)
            if isinstance(item, (tuple, list)) and len(item) == 2 and item[0] == key:
                return item[1]
        return default
    else:
        # Fallback: try to treat as dict
        return getattr(settings, 'get', lambda d: default)(key, default)
