import unittest
import banner


class TestBanner(unittest.TestCase):
    def test_banner_returns_string(self):
        # Test that banner returns a string, not bytes
        result = banner.banner('welcome')
        self.assertIsInstance(result, str)

    def test_banner_contains_name(self):
        # Test that the returned string contains the name
        result = banner.banner('welcome')
        self.assertIn('welcome', result)

    def test_banner_format(self):
        # Test the exact format: "== text =="
        result = banner.banner('welcome')
        self.assertEqual(result, "== welcome ==")

    def test_banner_no_crash(self):
        # Test that it doesn't crash (TypeError)
        try:
            banner.banner('welcome')
        except TypeError:
            self.fail("TypeError raised")


if __name__ == '__main__':
    unittest.main()

