import re

def parse_price(text):
    """'$1,234.50' -> 1234.5
    ' 7 ' -> 7.0
    None, '' or anything that is not a price -> None
    """
    if text is None:
        return None
    if not isinstance(text, str):
        return None

    # Strip surrounding whitespace
    text = text.strip()

    # If empty after stripping, return None
    if not text:
        return None

    # Remove optional leading '$'
    if text.startswith('$'):
        text = text[1:]

    # Remove commas
    text = text.replace(',', '')

    # Strip whitespace again just in case there were spaces around the number
    text = text.strip()

    # If empty after processing, return None
    if not text:
        return None

    # Check if it looks like a valid number (optional sign, digits, optional decimal)
    # Using regex to validate the string is a valid number format
    if not re.match(r'^-?\d+(\.\d+)?$', text):
        return None

    try:
        return float(text)
    except ValueError:
        return None

