def normalize_phone(raw):
    """Digits of a US phone number, e.g. '(555) 123-4567' -> '5551234567'.

    Requirement: Keep only the digits; drop a leading country code 1 from 11-digit numbers.
    Return None if the result is not exactly 10 digits, or if raw is None.
    """
    if raw is None:
        return None

    digits = "".join(ch for ch in raw if ch.isdigit())

    # If not exactly 10 or 11 digits, return None
    if len(digits) not in (10, 11):
        return None

    if len(digits) == 11:
        # Drop a leading country code 1 from 11-digit numbers
        if digits.startswith('1'):
            digits = digits[1:]
        else:
            # If it's 11 digits but doesn't start with 1, it's invalid
            return None

    # After processing, it must be exactly 10 digits
    if len(digits) != 10:
        return None

    return digits

