import os


def rotate(path, keep):
    """Rotate a log: path -> path.1 -> path.2 ... keeping at most `keep` old copies; path starts empty."""
    # First, remove the oldest file if it exists (path.<keep>)
    # This ensures we don't exceed keep count
    oldest = f"{path}.{keep}"
    if os.path.exists(oldest):
        os.remove(oldest)

    # Shift existing rotated files: path.<keep-1> -> path.<keep>, ..., path.1 -> path.2
    for i in range(keep, 0, -1):
        src = f"{path}.{i - 1}" if i > 1 else path
        dst = f"{path}.{i}"
        if i == 1:
            # For the first rotation, we move the current path to path.1
            if os.path.exists(src):
                os.replace(src, dst)
        else:
            # For subsequent rotations, we move path.<i-1> to path.<i>
            if os.path.exists(src):
                os.replace(src, dst)

    # Create an empty new log file at path
    open(path, "w").close()


if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        print("Usage: rotate.py <path> <keep>")
        sys.exit(1)
    rotate(sys.argv[1], int(sys.argv[2]))
