def dir_size(folder):
    """Total size in bytes of all files under folder."""
    total = 0
    for n in os.listdir(folder):
        path = os.path.join(folder, n)
        if os.path.isfile(path):
            total += os.path.getsize(path)
        elif os.path.isdir(path):
            total += dir_size(path)
    return total
