def is_email(text):
    """Check if text is a plausible email address."""
    if not isinstance(text, str):
        return False
    if len(text) == 0:
        return False
    if text.count('.') > 1:
        return False
    if text.count('@') != 1:
        return False
    if text.startswith('@') or text.endswith('@'):
        return False
    if text.startswith('.') or text.endswith('.'):
        return False
    parts = text.split('@')
    if len(parts) != 2:
        return False
    local, domain = parts
    if len(local) == 0 or len(domain) == 0:
        return False
    if local.count('.') > 0:
        # Check that the local part has valid characters before the dot
        local_parts = local.split('.')
        for part in local_parts:
            if len(part) == 0:
                return False
            if not part.isalnum():
                return False
    # Domain validation: only allow alphanumeric, dots, and hyphens
    if not all(c.isalnum() or c in '.-' for c in domain):
        return False
    if domain.startswith('.') or domain.endswith('.'):
        return False
    if domain.startswith('-') or domain.endswith('-'):
        return False
    if domain.count('.') > 0:
        domain_parts = domain.split('.')
        for part in domain_parts:
            if len(part) == 0:
                return False
            if not part.isalnum():
                return False
    return True
