import unittest
import sys
import os

# Add the current directory to the path so we can import solution
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from solution import due_date


class TestDueDate(unittest.TestCase):
    def test_basic_case(self):
        """Test due_date with a basic case."""
        self.assertEqual(due_date("20202015"), "20202016")

    def test_terms_days_default(self):
        """Test due_date with default terms_days (30)."""
        self.assertEqual(due_date("20202015"), "20202016")

    def test_terms_days_custom(self):
        """Test due_date with custom terms_days."""
        self.assertEqual(due_date("20202015", 1), "20202016")

    def test_edge_case_zero(self):
        """Test due_date with terms_days=0."""
        self.assertEqual(due_date("20202015", 0), "20202015")

    def test_edge_case_negative(self):
        """Test due_date with negative terms_days."""
        self.assertEqual(due_date("20202016", -1), "20202015")

    def test_edge_case_large(self):
        """Test due_date with large terms_days."""
        self.assertEqual(due_date("20202015", 100), "20202016")

    def test_edge_case_boundary(self):
        """Test due_date with boundary terms_days."""
        self.assertEqual(due_date("20202015", 30), "20202016")


if __name__ == "__main__":
    unittest.main()

