import unittest
from solution import search_key


class TestSearchKey(unittest.TestCase):
    def test_basic_ascii(self):
        """Test basic ASCII names are lowercased and stripped."""
        self.assertEqual(search_key("Hello World"), "hello world")

    def test_accents_removed(self):
        """Test that accents are removed."""
        self.assertEqual(search_key("Café Zoë"), "cafe zoe")

    def test_case_insensitive(self):
        """Test that case is normalized to lowercase."""
        self.assertEqual(search_key("HELLO WORLD"), "hello world")

    def test_whitespace_stripped(self):
        """Test that leading and trailing whitespace is stripped."""
        self.assertEqual(search_key("  Hello  "), "hello")

    def test_mixed_case_and_accents(self):
        """Test mixed case and accents together."""
        self.assertEqual(search_key("  Café  "), "cafe")

    def test_empty_string(self):
        """Test empty string returns empty string."""
        self.assertEqual(search_key(""), "")

    def test_only_whitespace(self):
        """Test string with only whitespace returns empty string."""
        self.assertEqual(search_key("   "), "")

    def test_special_characters(self):
        """Test special characters are handled appropriately."""
        self.assertEqual(search_key("John's Book"), "john's book")


if __name__ == '__main__':
    unittest.main()

